   async listMessages(query = '', maxResults = 100, pageToken = null) {
     try {
       const response = await this.gmail.users.messages.list({
         userId: 'me',
         q: query,
         maxResults,
         pageToken
       });

       return {
         messages: response.data.messages || [],
         nextPageToken: response.data.nextPageToken,
         resultSizeEstimate: response.data.resultSizeEstimate,
         historyId: response.data.historyId
       };
     } catch (error) {
       this.handleApiError(error, 'listMessages');
     }
   }

   async getMessageBatch(messageIds) {
     const batchSize = 10; // Optimize based on testing
     const messages = [];

     for (let i = 0; i < messageIds.length; i += batchSize) {
       const batch = messageIds.slice(i, i + batchSize);
       const promises = batch.map(id => 
         this.gmail.users.messages.get({
           userId: 'me',
           id,
           format: 'full'
         })
       );

       const results = await Promise.allSettled(promises);

       // Process results and handle any individual failures
       for (const result of results) {
         if (result.status === 'fulfilled') {
           messages.push(result.value.data);
         } else {
           console.error(`Failed to fetch message: ${result.reason}`);
           // Implement retry logic here
         }
       }

       // Apply exponential backoff to avoid rate limiting
       if (i + batchSize < messageIds.length) {
         await new Promise(resolve => setTimeout(resolve, 100));
       }
     }

     return messages;
   }
   ```
2. Implement a complete pagination handler for large mailboxes:
   ```javascript
   async fetchAllMessages(query = '', batchSize = 100) {
     let pageToken = null;
     let allMessages = [];
     let latestHistoryId = null;

     do {
       const result = await this.listMessages(query, batchSize, pageToken);
       if (result.messages && result.messages.length > 0) {
         allMessages = allMessages.concat(result.messages);
       }

       pageToken = result.nextPageToken;
       latestHistoryId = result.historyId || latestHistoryId;
     } while (pageToken);

     return { messages: allMessages, historyId: latestHistoryId };
   }
   ```
